CREATE TABLE users (id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, role VARCHAR(16) NOT NULL DEFAULT 'customer', sample_user BOOLEAN NOT NULL DEFAULT FALSE, session_version INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_profiles (user_id VARCHAR(36) PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, phone VARCHAR(20), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_preferences (user_id VARCHAR(36) PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, preferred_brands VARCHAR(1000) NOT NULL DEFAULT '', notifications_enabled BOOLEAN NOT NULL DEFAULT TRUE, price_increase_alerts BOOLEAN NOT NULL DEFAULT FALSE, replenishment_alerts BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_categories (id VARCHAR(50) PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id VARCHAR(60) PRIMARY KEY, category_id VARCHAR(50) NOT NULL, name VARCHAR(150) NOT NULL, brand VARCHAR(100) NOT NULL, variant_name VARCHAR(100) NOT NULL, description VARCHAR(1000) NOT NULL, color VARCHAR(20) NOT NULL, art VARCHAR(20) NOT NULL, image_url VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (category_id) REFERENCES product_categories(id));
CREATE TABLE product_variants (id VARCHAR(60) PRIMARY KEY, product_id VARCHAR(60) NOT NULL, pack_label VARCHAR(60) NOT NULL, amount_base DECIMAL(12,3) NOT NULL CHECK(amount_base>0), base_unit VARCHAR(10) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(product_id,amount_base,base_unit), FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE grocery_platforms (id VARCHAR(20) PRIMARY KEY, name VARCHAR(80) NOT NULL, delivery_minor BIGINT, handling_minor BIGINT, minimum_minor BIGINT, free_delivery_minor BIGINT, fee_source VARCHAR(40) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE delivery_locations (id VARCHAR(60) PRIMARY KEY, name VARCHAR(100) NOT NULL, city VARCHAR(60) NOT NULL, postcode VARCHAR(6) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE platform_locations (platform_id VARCHAR(20) NOT NULL, location_id VARCHAR(60) NOT NULL, available BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(platform_id,location_id), FOREIGN KEY (platform_id) REFERENCES grocery_platforms(id), FOREIGN KEY (location_id) REFERENCES delivery_locations(id));
CREATE TABLE platform_products (id VARCHAR(80) PRIMARY KEY, platform_id VARCHAR(20) NOT NULL, variant_id VARCHAR(60) NOT NULL, retailer_sku VARCHAR(150) NOT NULL, source_url VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(platform_id,variant_id), UNIQUE(platform_id,retailer_sku), FOREIGN KEY (platform_id) REFERENCES grocery_platforms(id), FOREIGN KEY (variant_id) REFERENCES product_variants(id));
CREATE TABLE location_prices (id VARCHAR(100) PRIMARY KEY, platform_product_id VARCHAR(80) NOT NULL, location_id VARCHAR(60) NOT NULL, price_minor BIGINT CHECK(price_minor>=0), mrp_minor BIGINT CHECK(mrp_minor>=0), availability VARCHAR(20) NOT NULL, observed_at TIMESTAMP NOT NULL, source VARCHAR(40) NOT NULL, verification VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(platform_product_id,location_id), FOREIGN KEY (platform_product_id) REFERENCES platform_products(id), FOREIGN KEY (location_id) REFERENCES delivery_locations(id));
CREATE INDEX idx_prices_location ON location_prices(location_id,observed_at);
CREATE TABLE price_history (id VARCHAR(36) PRIMARY KEY, platform_product_id VARCHAR(80) NOT NULL, location_id VARCHAR(60) NOT NULL, price_minor BIGINT NOT NULL CHECK(price_minor>=0), observed_at TIMESTAMP NOT NULL, source VARCHAR(40) NOT NULL, verification VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(platform_product_id,location_id,observed_at), FOREIGN KEY (platform_product_id) REFERENCES platform_products(id), FOREIGN KEY (location_id) REFERENCES delivery_locations(id));
CREATE INDEX idx_history_lookup ON price_history(platform_product_id,location_id,observed_at);
CREATE TABLE shopping_carts (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, location_id VARCHAR(60) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,location_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (location_id) REFERENCES delivery_locations(id));
CREATE TABLE cart_items (id VARCHAR(36) PRIMARY KEY, cart_id VARCHAR(36) NOT NULL, variant_id VARCHAR(60) NOT NULL, quantity INT NOT NULL CHECK(quantity BETWEEN 1 AND 99), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(cart_id,variant_id), FOREIGN KEY (cart_id) REFERENCES shopping_carts(id) ON DELETE CASCADE, FOREIGN KEY (variant_id) REFERENCES product_variants(id));
CREATE TABLE purchase_preferences (cart_item_id VARCHAR(36) PRIMARY KEY REFERENCES cart_items(id) ON DELETE CASCADE, intent VARCHAR(20) NOT NULL, max_price_minor BIGINT, target_price_minor BIGINT, max_unit_price_minor BIGINT, bulk_budget_minor BIGINT, max_useful_packs INT, consumption_days INT, monitor_price BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE price_watchlists (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, variant_id VARCHAR(60) NOT NULL, location_id VARCHAR(60) NOT NULL, target_minor BIGINT NOT NULL CHECK(target_minor>0), enabled BOOLEAN NOT NULL DEFAULT TRUE, last_price_minor BIGINT, last_available BOOLEAN, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,variant_id,location_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (variant_id) REFERENCES product_variants(id), FOREIGN KEY (location_id) REFERENCES delivery_locations(id));
CREATE TABLE price_alerts (id VARCHAR(36) PRIMARY KEY, watchlist_id VARCHAR(36) NOT NULL, event_key VARCHAR(200) NOT NULL UNIQUE, event_type VARCHAR(30) NOT NULL, observed_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (watchlist_id) REFERENCES price_watchlists(id) ON DELETE CASCADE);
CREATE TABLE notifications (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, title VARCHAR(150) NOT NULL, body VARCHAR(1000) NOT NULL, kind VARCHAR(30) NOT NULL, dedupe_key VARCHAR(200) NOT NULL UNIQUE, sample BOOLEAN NOT NULL, read_at TIMESTAMP, delivery_status VARCHAR(20) NOT NULL DEFAULT 'IN_APP', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX idx_notifications_owner ON notifications(user_id,created_at);
CREATE TABLE shopping_history (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, location_id VARCHAR(60) NOT NULL, platform_id VARCHAR(20) NOT NULL, total_minor BIGINT NOT NULL CHECK(total_minor>=0), savings_minor BIGINT NOT NULL DEFAULT 0, purchased_at TIMESTAMP NOT NULL, sample BOOLEAN NOT NULL, request_key VARCHAR(80) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,request_key), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (location_id) REFERENCES delivery_locations(id), FOREIGN KEY (platform_id) REFERENCES grocery_platforms(id));
CREATE TABLE shopping_history_items (id VARCHAR(36) PRIMARY KEY, history_id VARCHAR(36) NOT NULL, variant_id VARCHAR(60) NOT NULL, quantity INT NOT NULL CHECK(quantity>0), unit_price_minor BIGINT NOT NULL CHECK(unit_price_minor>=0), category_id VARCHAR(50) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (history_id) REFERENCES shopping_history(id) ON DELETE CASCADE, FOREIGN KEY (variant_id) REFERENCES product_variants(id), FOREIGN KEY (category_id) REFERENCES product_categories(id));
CREATE TABLE replenishment_records (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, variant_id VARCHAR(60) NOT NULL, cycle_days INT NOT NULL CHECK(cycle_days BETWEEN 1 AND 365), last_purchased_at TIMESTAMP NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,variant_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (variant_id) REFERENCES product_variants(id));
CREATE TABLE monthly_budgets (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, budget_month VARCHAR(7) NOT NULL, limit_minor BIGINT NOT NULL CHECK(limit_minor>0), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,budget_month), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE budget_transactions (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, history_id VARCHAR(36), category_id VARCHAR(50) NOT NULL, amount_minor BIGINT NOT NULL CHECK(amount_minor>0), occurred_at TIMESTAMP NOT NULL, note VARCHAR(200) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (history_id) REFERENCES shopping_history(id), FOREIGN KEY (category_id) REFERENCES product_categories(id));
CREATE INDEX idx_spending_owner_date ON budget_transactions(user_id,occurred_at);
CREATE TABLE recipes (id VARCHAR(60) PRIMARY KEY, name VARCHAR(150) NOT NULL, servings INT NOT NULL CHECK(servings>0), instructions TEXT NOT NULL, source VARCHAR(150) NOT NULL, sample BOOLEAN NOT NULL, color VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE recipe_ingredients (id VARCHAR(36) PRIMARY KEY, recipe_id VARCHAR(60) NOT NULL, product_id VARCHAR(60) NOT NULL, amount_base DECIMAL(12,3) NOT NULL CHECK(amount_base>0), base_unit VARCHAR(10) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(recipe_id,product_id), FOREIGN KEY (recipe_id) REFERENCES recipes(id) ON DELETE CASCADE, FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE user_pantry (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, product_id VARCHAR(60) NOT NULL, amount_base DECIMAL(12,3) NOT NULL CHECK(amount_base>=0), base_unit VARCHAR(10) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,product_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE refresh_tokens (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, expires_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE device_tokens (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL, token VARCHAR(1000) NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE saved_products (user_id VARCHAR(36) NOT NULL, variant_id VARCHAR(60) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,variant_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (variant_id) REFERENCES product_variants(id));

